    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a_intervals:
        return []

    # Merge overlapping/touching intervals in b
    merged_b = []
    for start, end in b_intervals:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    # Subtract b from a
    result = []
    for a_start, a_end in a_intervals:
        current_intervals = [[a_start, a_end]]

        for b_start, b_end in merged_b:
            new_intervals = []
            for curr_start, curr_end in current_intervals:
                if b_end <= curr_start or b_start >= curr_end:
                    # No overlap
                    new_intervals.append([curr_start, curr_end])
                else:
                    # There is overlap
                    if curr_start < b_start:
                        new_intervals.append([curr_start, b_start])
                    if b_end < curr_end:
                        new_intervals.append([b_end, curr_end])
            current_intervals = new_intervals

        result.extend(current_intervals)

    # Merge touching/overlapping intervals in result
    if not result:
        return []

    result.sort()
    merged_result = [result[0]]
    for start, end in result[1:]:
        if start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

